#include <algorithm>
#include <print>
#include <string>
#include <vector>

struct Student {
    std::string name;
    int score;
};

int main() {
    std::vector<Student> v = {{"Ann", 88}, {"Bob", 72}, {"Cid", 88}, {"Dot", 95}};
    std::sort(v.begin(), v.end(), [](const Student& a, const Student& b) {
        if (a.score != b.score) return a.score > b.score;
        return a.name < b.name;
    });
    for (const Student& s : v) std::println("{} {}", s.name, s.score);
    std::stable_sort(v.begin(), v.end(), [](const Student& a, const Student& b) {
        return a.score > b.score;
    });
    std::println("stable_sort 之后:");   // 同分的两位仍然保持原来的先后
    return 0;
}

